    """Calculate usage percentage."""
    limit = data['limit']
    used = data['used']
    return (used / limit) * 100 if limit > 0 else 0

def get_warning_level(percentage):
    """Determine warning level based on percentage."""
    if percentage >= 95:
        return '🚨', 'Emergency', '#dc3545', 'CRITICAL'
    elif percentage >= 90:
        return '🔴', 'Critical Warning', '#dc3545', 'RED'
    elif percentage >= 75:
        return '🔶', 'High Warning', '#fd7e14', 'ORANGE'
    elif percentage >= 50:
        return '🟠', 'Medium Warning', '#ffc107', 'YELLOW'
    elif percentage >= 25:
        return '🟡', 'Low Warning', '#28a745', 'GREEN'
    else:
        return '✅', 'OK', '#28a745', 'GREEN'

def generate_dashboard(data):
    """Generate HTML dashboard content."""
    percentage = calculate_usage(data)
    remaining = data['limit'] - data['used']
    indicator, warning_name, color, zone = get_warning_level(percentage)

