    return html

def main():
    # Load data
    data = load_session_data()

    # Generate dashboard
    html = generate_dashboard(data)

    # Save to file
    DASHBOARD_FILE.write_text(html, encoding='utf-8')

    # Print status
    percentage = calculate_usage(data)
    indicator, warning_name, color, zone = get_warning_level(percentage)

    print(f"{indicator} Token Alert Dashboard")
    print(f"="*50)
    print(f"Usage: {percentage:.1f}%")
    print(f"Status: {warning_name} ({zone} Zone)")
    print(f"\nDashboard saved to: {DASHBOARD_FILE}")
    print(f"\nTo view dashboard, open:")
    print(f"  {DASHBOARD_FILE}")

    # Try to open in browser
    try:
        webbrowser.open(f'file://{DASHBOARD_FILE}')
        print(f"\nOpening in browser...")
    except Exception as e:
        print(f"\nCould not open browser: {e}")
        print(f"Please open the file manually in your browser.")

if __name__ == '__main__':
    main()
